do $$
declare tenant uuid:=gen_random_uuid();other_tenant uuid:=gen_random_uuid();admin_user uuid:=gen_random_uuid();school_user uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();school uuid:=gen_random_uuid();ev uuid:=gen_random_uuid();other_ev uuid:=gen_random_uuid();sport uuid:=gen_random_uuid();cat uuid:=gen_random_uuid();person uuid:=gen_random_uuid();guardian uuid:=gen_random_uuid();part uuid;reg jsonb;art jsonb;photo jsonb;layout jsonb;changed jsonb;model jsonb;first_version uuid;first_badge uuid;issued jsonb;history jsonb;denied boolean;
begin
 begin
 insert into auth.users(id) values(admin_user),(school_user),(outsider);
 insert into public.institutions(id,name,slug) values(tenant,'Modelo de crachá','template-'||tenant),(other_tenant,'Outro','template-'||other_tenant);
 insert into public.institution_memberships(institution_id,user_id,role,status) values(tenant,admin_user,'admin','approved'),(other_tenant,outsider,'admin','approved');
 insert into public.schools(id,institution_id,name) values(school,tenant,'Escola');
 insert into public.events(id,institution_id,name,edition,status) values(ev,tenant,'Evento da arte','2026','open'),(other_ev,tenant,'Outro evento','2027','open');
 insert into public.event_modalities(id,institution_id,event_id,name,classification) values(sport,tenant,ev,'Atletismo','individual');
 insert into public.event_categories(id,institution_id,event_id,modality_id,name,participation) values(cat,tenant,ev,sport,'Livre','individual');
 insert into public.people(id,institution_id,full_name,birth_date,cpf,gender) values(person,tenant,'Nome para a arte','2010-01-01','52998224725','Feminino'),(guardian,tenant,'Responsável','1990-01-01','11144477735','Feminino');
 insert into public.school_people(institution_id,school_id,person_id,role,status,user_id) values(tenant,school,person,'athlete','approved',null),(tenant,school,guardian,'responsible','approved',school_user);
 layout:='{"width":86,"height":130,"fit":"contain","fields":[{"key":"photo","x":31,"y":20,"w":38,"h":33,"fontSize":12,"color":"#163453","align":"center"},{"key":"person_name","x":5,"y":57,"w":90,"h":12,"fontSize":14,"color":"#163453","align":"center"},{"key":"school_name","x":5,"y":73,"w":90,"h":9,"fontSize":10,"color":"#163453","align":"center"},{"key":"modalities","x":5,"y":85,"w":90,"h":10,"fontSize":10,"color":"#163453","align":"center"}]}';
 perform set_config('request.jwt.claim.sub',school_user::text,true);execute 'set local role authenticated';
 denied:=false;begin perform public.siep_prepare_badge_art(ev,'arte.png','image/png',20);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Escola enviou arte';end if;
 denied:=false;begin perform public.siep_save_badge_template(ev,'athlete',0,layout);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Escola configurou modelo';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',admin_user::text,true);execute 'set local role authenticated';
 denied:=false;begin perform public.siep_prepare_badge_art(ev,'arte.svg','image/svg+xml',20);exception when check_violation then denied:=true;end;if not denied then raise exception 'SVG aceito';end if;
 art:=public.siep_prepare_badge_art(ev,'arte.png','image/png',20);
 denied:=false;begin perform public.siep_finalize_badge_art((art->>'id')::uuid);exception when check_violation then denied:=true;end;if not denied then raise exception 'Upload ausente foi confirmado';end if;
 insert into storage.objects(bucket_id,name,owner_id,metadata) values('siep-badge-art',art->>'path',admin_user::text,'{"size":20,"mimetype":"image/png"}');perform public.siep_finalize_badge_art((art->>'id')::uuid);
 model:=public.siep_save_badge_template(ev,'athlete',0,layout,(art->>'id')::uuid);first_version:=(model->>'version_id')::uuid;
 if model->>'version'<>'1' or model#>>'{background,objectPath}'<>art->>'path' then raise exception 'Arte/modelo não persistiu';end if;
 denied:=false;begin perform public.siep_save_badge_template(ev,'athlete',0,layout);exception when serialization_failure then denied:=true;end;if not denied then raise exception 'Revisão antiga aceita';end if;
 denied:=false;begin perform public.siep_save_badge_template(other_ev,'athlete',0,layout,(art->>'id')::uuid);exception when check_violation then denied:=true;end;if not denied then raise exception 'Arte de outro evento aceita';end if;
 denied:=false;begin perform public.siep_save_badge_template(ev,'athlete',1,jsonb_set(layout,'{fields,0,x}','99'));exception when check_violation then denied:=true;end;if not denied then raise exception 'Campo fora do crachá aceito';end if;
 denied:=false;begin perform public.siep_save_badge_template(ev,'athlete',1,layout#-'{fields,1}');exception when check_violation then denied:=true;end;if not denied then raise exception 'Nome obrigatório removido';end if;
 changed:=jsonb_set(layout,'{fields,3,key}','"functions"');perform public.siep_save_badge_template(ev,'staff',0,changed);
 if public.siep_badge_template(ev,'staff')->>'id'=model->>'id' then raise exception 'Modelos de perfis não foram separados';end if;
 reg:=public.siep_save_participation(ev,school,person,array[cat],'{}',true);part:=(reg->>'id')::uuid;
 reg:=public.siep_complete_registration(gen_random_uuid(),ev,school,cat,null,jsonb_build_array(jsonb_build_object('participation_id',part,'slot_number',1)),'[]');
 reg:=public.siep_transition_registration((reg->>'id')::uuid,(reg->>'revision')::int,'approved','Conferido');
 photo:=public.siep_prepare_person_photo(person,'foto.png','image/png',21);insert into storage.objects(bucket_id,name,owner_id,metadata) values('siep-person-photos',photo->>'path',admin_user::text,'{"size":21,"mimetype":"image/png"}');perform public.siep_finalize_person_photo((photo->>'id')::uuid);
 issued:=public.siep_issue_event_badges(ev,jsonb_build_array(jsonb_build_object('person_id',person,'school_id',school,'role','athlete')));first_badge:=(issued#>>'{0,id}')::uuid;
 if issued#>>'{0,snapshot,modalities}'<>'Atletismo' or issued#>>'{0,snapshot,badge_template,layout,width}'<>'86' or issued#>>'{0,snapshot,badge_template,version}'<>'1' then raise exception 'Impressão não recebeu dados e modelo corretos';end if;
 execute 'reset role';
 if not exists(select 1 from public.event_badges where id=first_badge and template_version_id=first_version and not(snapshot->'badge_template' ? 'layout')) then raise exception 'Layout foi duplicado no armazenamento de cada crachá';end if;
 execute 'set local role authenticated';
 changed:=jsonb_set(layout,'{fields,1,x}','7');
 changed:=jsonb_set(changed,'{fields}',(changed->'fields')||'{"key":"qr_code","x":72,"y":40,"w":22,"h":14.55,"fontSize":11,"color":"#163453","align":"center"}'::jsonb);
 denied:=false;begin perform public.siep_save_badge_template(ev,'athlete',1,jsonb_set(changed,'{fields,4,w}','2'));exception when check_violation then denied:=true;end;if not denied then raise exception 'QR Code pequeno aceito';end if;
 model:=public.siep_save_badge_template(ev,'athlete',1,changed,(art->>'id')::uuid);
 issued:=public.siep_issue_event_badges(ev,jsonb_build_array(jsonb_build_object('person_id',person,'school_id',school,'role','athlete')));
 if issued#>>'{0,snapshot,badge_template,version}'<>'2' or issued#>>'{0,snapshot,badge_template,layout,fields,4,key}' is distinct from 'qr_code' then raise exception 'Emissão nova usou versão antiga';end if;
 history:=public.siep_badge_history(tenant,ev,school);
 if not exists(select 1 from jsonb_array_elements(history) h where h->>'id'=first_badge::text and h#>>'{snapshot,badge_template,version}'='1' and h#>>'{snapshot,badge_template,layout,fields,1,x}'='5') then raise exception 'Reimpressão trocou posição/arte antiga';end if;
 perform public.siep_save_badge_template(ev,'athlete',2,changed,null);
 if not exists(select 1 from storage.objects where bucket_id='siep-badge-art' and name=art->>'path') then raise exception 'Arte histórica inacessível';end if;
 execute 'reset role';denied:=false;begin update public.badge_template_versions set layout='{}' where id=first_version;exception when check_violation then denied:=true;end;if not denied then raise exception 'Histórico do modelo alterado';end if;
 denied:=false;begin delete from public.badge_art_assets where id=(art->>'id')::uuid;exception when foreign_key_violation then denied:=true;end;if not denied then raise exception 'Arte histórica excluída';end if;
 perform set_config('request.jwt.claim.sub',school_user::text,true);execute 'set local role authenticated';
 if exists(select 1 from storage.objects where bucket_id='siep-badge-art' and name=art->>'path') then raise exception 'Escola leu a arte privada';end if;
 denied:=false;begin perform public.siep_badge_history(tenant,ev);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Escola leu emissões';end if;
 execute 'reset role';perform set_config('request.jwt.claim.sub',outsider::text,true);execute 'set local role authenticated';
 denied:=false;begin perform public.siep_badge_template(ev,'athlete');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Outra instituição leu modelo';end if;
 execute 'reset role';if has_function_privilege('anon','public.siep_save_badge_template(uuid,text,integer,jsonb,uuid)','execute') then raise exception 'RPC pública';end if;
 raise exception 'rollback_custom_badge_templates' using errcode='ZX001';
 exception when sqlstate 'ZX001' then null;
 end;
end $$;
